import{c as e,Q as s,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"Master Claude With Fable 5: 6 Rules Straight From Anthropic's Docs","description":"","frontmatter":{"url":"https://x.com/0xmoysei/status/2072808742274392194","title":"Master Claude With Fable 5: 6 Rules Straight From Anthropic's Docs","author":"0xMoysei","archived":"2026-07-03T00:00:00.000Z","handle":"@0xMoysei","published":"2026-07-02T00:00:00.000Z","stats":"30 likes · 3 retweets · 67 bookmarks · 30068 views","tags":["fable5","prompting","reasoning-extraction","verification","effort","self-audit"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@0xMoysei-392194.md","filePath":"research/tweets/2026-07-02-@0xMoysei-392194.md","lastUpdated":1785909234000}`),o={name:"research/tweets/2026-07-02-@0xMoysei-392194.md"};function i(r,t,l,p,d,c){return s(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="master-claude-with-fable-5-6-rules-straight-from-anthropic-s-docs-—-0xmoysei" tabindex="-1">Master Claude With Fable 5: 6 Rules Straight From Anthropic&#39;s Docs — @0xMoysei <a class="header-anchor" href="#master-claude-with-fable-5-6-rules-straight-from-anthropic-s-docs-—-0xmoysei" aria-label="Permalink to &quot;Master Claude With Fable 5: 6 Rules Straight From Anthropic&#39;s Docs — @0xMoysei&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/0xmoysei/status/2072808742274392194" target="_blank" rel="noreferrer">https://x.com/0xmoysei/status/2072808742274392194</a><strong>作者</strong>：0xMoysei（@0xMoysei） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：30 likes · 3 retweets · 67 bookmarks · 30068 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：引用 Anthropic 官方 prompting guide，將 8 條核心規則整理為可直接套用的 CLAUDE.md 片段和 prompt 模板。</p><p><strong>定價背景</strong>：Fable 5 = $10/M input, $50/M output, 1M context window, 128k output ceiling。</p><h3 id="_8-條核心規則" tabindex="-1">8 條核心規則 <a class="header-anchor" href="#_8-條核心規則" aria-label="Permalink to &quot;8 條核心規則&quot;">​</a></h3><p><strong>Rule 1：給出 Why（意圖前置）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m working on [larger task] for [who it&#39;s for].</span></span>
<span class="line"><span>They need [what the output enables].</span></span>
<span class="line"><span>With that in mind: [your actual request].</span></span></code></pre></div><p><strong>Rule 2：設定明確否定（邊界塊）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When I describe a problem or ask a question, the</span></span>
<span class="line"><span>deliverable is your assessment. Report what you</span></span>
<span class="line"><span>find and stop. Do not fix, send, edit, or delete</span></span>
<span class="line"><span>anything until I say go.</span></span></code></pre></div><p>→ Fable 5 會主動採取未被要求的行動（起草未請求的 email、建立 git 備份分支）。每個指令都需要配對「不做什麼」。</p><p><strong>Rule 3：Effort Dial 對齊</strong></p><ul><li>low/medium → 常規任務</li><li>high → Anthropic 推薦默認值</li><li>xhigh → 能力敏感工作</li><li><strong>關鍵洞察</strong>：Fable 5 low effort 往往超過舊模型 xhigh 性能，成本遠低；不要在 changelog 摘要上跑 xhigh。</li></ul><p><strong>Rule 4：停止過度規劃，讓它行動</strong></p><p>直接加入 CLAUDE.md 的一行：</p><blockquote><p><strong>&quot;When you have enough information to act, act.&quot;</strong></p></blockquote><p>替代「先研究所有東西再規劃」。深度研究用 Opus 4.8 → PRD → 再給 Fable 執行。</p><p><strong>Rule 5：要求它證明（驗證塊）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before reporting progress, audit each claim against</span></span>
<span class="line"><span>a tool result from this session. Only report work</span></span>
<span class="line"><span>you can point to evidence for. If something is not</span></span>
<span class="line"><span>verified, say so explicitly. If tests fail, say so</span></span>
<span class="line"><span>with the output. If a step was skipped, say that.</span></span></code></pre></div><p>→ 在 Anthropic 測試中幾乎消除長 agentic run 的虛假狀態報告。<strong>建議寫入 skills、agents 和 CLAUDE.md，而不是每次 paste。</strong></p><p><strong>Rule 6：⚠️ 不要要求原始推理（reasoning_extraction 詳解）</strong></p><ul><li>分類器觸發三類：攻擊性網安技術 / 生物與生命科學 / <strong>思考內容提取（extraction of the model&#39;s own thinking）</strong></li><li>系統 prompt 中的「explain your reasoning」固定語句 → 觸發 reasoning_extraction 拒絕</li><li><strong>觸發後 reroute 到 Opus 4.8，rate 約 5% sessions</strong></li><li><strong>⚠️ Reroute 後持續生效</strong>：觸發語句留在 context 中 → 下一個 request 再次被 bounce；<code>/model fable</code> 可手動切回但語句不清除會再次觸發</li><li><strong>修復</strong>：審計 system prompt 和 CLAUDE.md，移除推理回顯指令，改用「summarized thinking display」設定</li></ul><p><strong>Rule 7：先刪除再增加（減法原則）</strong></p><p>自我審計 prompt（直接使用）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reflect on my past Claude Code sessions to find the</span></span>
<span class="line"><span>highest-impact improvements to my setup. Cluster</span></span>
<span class="line"><span>findings across sessions. Per cluster, decide: new</span></span>
<span class="line"><span>skill, new automation, a fix, or nothing. Write the</span></span>
<span class="line"><span>candidates to a file. Diagnosis only, no changes.</span></span></code></pre></div><p>→ 39 個 session 的一次跑出：需建的 skill、可自動化的 skill、CLAUDE.md 中誤導模型的過時行</p><p><strong>Rule 8：高槓桿目標（3 個類型）</strong></p><ol><li>大規模 Code Review：整個最大 repo，平行 reviewer，按嚴重度排重複發現</li><li>Clone 你付費的軟體：Opus 研究 → PRD → Fable 長期執行（案例：21,000 行 TypeScript / 90+ commits）</li><li>重建工作流：跑 Rule 7 審計，讓 Fable 寫它自己推薦的 SKILL.md 和 automation</li></ol><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：引用 Anthropic 官方文件的 8 條 Fable 5 規則，最關鍵是 reasoning_extraction 的「reroute 持續生效」機制、Rule 5 驗證塊（反虛假進度）和 Rule 7 自我審計 prompt。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>⚠️ reasoning_extraction reroute 持續生效</strong>：觸發語句留在 context → 每次 request 都 bounce，必須清除 context 才能恢復</li><li><strong>驗證塊應內建</strong>：寫入 skills/agents/CLAUDE.md，不是每次 paste（10 次裡只記得 6 次的效率）</li><li><strong>&quot;When you have enough information to act, act&quot;</strong>：替換過度規劃的一行指令</li><li><strong>Effort 反直覺</strong>：Fable low 常超越舊模型 xhigh；高 effort 留給真正艱難的任務</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Fable 5 定價：$10/M input, $50/M output</li><li>reasoning_extraction reroute rate：約 5% sessions</li><li>Rule 5 驗證塊（Anthropic 測試：幾乎消除虛假進度報告）</li><li>Rule 7 自我審計 prompt（session history → ranked batch list）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>「reroute 持續生效」是三篇文章（wquguru/0xMoysei/KSimback）中最具體的機制描述</li><li>Rule 5 驗證塊 + 要求建入 CLAUDE.md 的建議直接對齊 workspace 的 unverified_success 閘門</li><li>Rule 7 自我審計 prompt 是少見的「使用 Fable 改進 Fable 設定」的操作化方法</li><li>整體與 wquguru 高度重疊，但 reroute 持續性和自我審計 prompt 是增量</li><li>文章聲稱「6 Rules Straight From Anthropic&#39;s Docs」但實際有 8 條規則，標題和內容不一致</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>驗證塊、自我審計 prompt、&quot;act when ready&quot; 句可直接寫入；reroute 修復流程可行動</td></tr><tr><td>B. 創新性 (20%)</td><td>6.5/10</td><td>reroute 持續性是新細節；自我審計 prompt 是新操作；整體規則高度重疊</td></tr><tr><td>C. 證據品質 (20%)</td><td>7.5/10</td><td>明確引用 Anthropic docs；5% reroute rate 具體；Anthropic 測試數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>7.5/10</td><td>reasoning_extraction 機制深度（持續性+修復）；驗證塊設計原理</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>驗證和推理提取規則跨模型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.4/10</strong></td><td>8×0.3+6.5×0.2+7.5×0.2+7.5×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：驗證塊模板補充 core.md §TEST；reasoning_extraction reroute 持續性補充 subagent-strategy.md；自我審計 prompt 可加入 maintenance-protocol.md；&quot;act when ready&quot; 句補充 output-discipline.md 或 CLAUDE.md。</p>`,42)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
